# [doc = " Generate an RFC-0014 **recovery scaffold** for an error `class` under a named, bounded [`RecoveryProfile`]"] # [doc = " — an explicit handler skeleton the author completes. This is the actionable form of the RFC-0015 §9"] # [doc = " "this class is only logged — add a handler?" advisory. It is **always** a scaffold (never applied): the"] # [doc = " decision to recover is declared, bounded, and opt-in (A2/I4/I5). The L1 surface syntax for handlers is"] # [doc = " RFC-0014's (not yet in the parser), so this is an illustrative, clearly-marked skeleton."] # [must_use] pub fn recovery_scaffold (class : & str , profile : RecoveryProfile) -> String { let body = match profile { RecoveryProfile :: Strict => { "    // strict: propagate (no recovery) — the honest default" . to_owned () } RecoveryProfile :: Resilient => format ! ("    // resilient: bounded retry(<={}) on `{class}`; if every attempt fails, propagate (I1/I4)
\
             \x20   retry(max = {}) {{ /* todo: the recoverable action */ }}" , mycelium_lsp :: baseline :: RESILIENT_MAX_ATTEMPTS , mycelium_lsp :: baseline :: RESILIENT_MAX_ATTEMPTS) , } ; format ! ("// recovery scaffold (opt-in, bounded — RFC-0014 I1/I5; complete or delete):
\
         handle {class} with {} {{
{body}
}}" , profile . as_str ()) }
